npm install --ignore-scripts --no-audit --no-fund 2>&1 | tail -3; ls; git -C /work/repo check-ignore -v node_modules/x || true

sed 's/"ON_FAILURE"/"SOMETIMES"/; s/dockerfilePath/dockerFilePath/' railway.ts > /tmp/neg.ts && cp /tmp/neg.ts ./__neg.ts && /tmp/tsc/node_modules/.bin/tsc --noEmit --strict --module nodenext --moduleResolution nodenext --target es2022 __neg.ts 2>&1 | cut -c1-150; rm -f __neg.ts
cat > /tmp/dump_iac.mjs <<'EOF'
import { createRailwayContext } from "/work/repo/.railway/node_modules/railway/dist/iac/index.js";
const mod = await import(process.argv[2]);
const proj = await mod.default(createRailwayContext({ command: "plan" }), (n, d) => ({ name: n, ...d }));
const nodes = proj.resources.flat(Infinity);
console.log("project:", proj.name, "| resources:", nodes.map(n => n.address).join(", "));
const api = nodes.find(n => n.name === "api");
const { address, type, kind, name, ...rest } = api;
console.log(JSON.stringify(rest, null, 2));
EOF
node /tmp/dump_iac.mjs /work/repo/.railway/railway.ts 2>&1 | grep -v ExperimentalWarning
